def containVirus(isInfected: list[list[int]]) -> int:
    R, C = len(isInfected), len(isInfected[0])
    def get_regions():
        visited = set()
        regions = []
        for r in range(R):
            for c in range(C):
                if isInfected[r][c] == 1 and (r, c) not in visited:
                    cells = set()
                    threatened = set()
                    walls = 0
                    stack = [(r, c)]
                    visited.add((r, c))
                    while stack:
                        cr, cc = stack.pop()
                        cells.add((cr, cc))
                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < R and 0 <= nc < C:
                                if isInfected[nr][nc] == 1 and (nr, nc) not in visited:
                                    visited.add((nr, nc))
                                    stack.append((nr, nc))
                                elif isInfected[nr][nc] == 0:
                                    walls += 1
                                    threatened.add((nr, nc))
                    regions.append((cells, threatened, walls))
        return regions
    total_walls = 0
    while True:
        regions = get_regions()
        if not regions: break
        regions.sort(key=lambda x: len(x[1]))
        target = regions.pop()
        total_walls += target[2]
        for r, c in target[0]:
            isInfected[r][c] = -1
        if not regions: break
        for cells, threatened, _ in regions:
            for r, c in threatened:
                isInfected[r][c] = 1
    return total_walls

